async function startRigTest(renderer2, params2) {
  const asset = await loadCatAsset();
  const scene = new Scene();
  scene.background = new Color(9080726);
  const group = new Group();
  scene.add(group);
  group.add(asset.bones[0]);
  let mat = new MeshStandardMaterial({ color: 12169640, roughness: 0.55 });
  const wbone = params2.get("wbone");
  if (wbone) {
    const bi = asset.bones.findIndex((b) => b.name === wbone);
    const si = asset.geo.getAttribute("skinIndex"), sw = asset.geo.getAttribute("skinWeight");
    const col = new Float32Array(si.count * 3);
    for (let v2 = 0; v2 < si.count; v2++) {
      let w = 0;
      for (let k = 0; k < 4; k++) if (si.array[v2 * 4 + k] === bi) w += sw.array[v2 * 4 + k] / 255;
      col[v2 * 3] = w;
      col[v2 * 3 + 1] = 0.15;
      col[v2 * 3 + 2] = 1 - w;
    }
    asset.geo.setAttribute("color", new BufferAttribute(col, 3));
    mat = new MeshStandardMaterial({ vertexColors: true, roughness: 0.7 });
  }
  const mesh = new SkinnedMesh(asset.geo, mat);
  group.add(mesh);
  group.updateMatrixWorld(true);
  const skeleton = new Skeleton(asset.bones);
  mesh.bind(skeleton);
  mesh.morphTargetInfluences[0] = Number(params2.get("grin") || 0);
  const white = new MeshStandardMaterial({ color: 16777215, roughness: 0.3 });
  const attach = (geo, boneName, material) => {
    const m = new Mesh(geo, material);
    m.position.copy(asset.restWorld[boneName]).negate();
    asset.byName[boneName].add(m);
    return m;
  };
  if (params2.get("teeth") !== "0") {
    attach(asset.teethUpper, "head", white);
    attach(asset.teethLower, "jaw", white);
  }
  const lips = attach(asset.lipsGeo, "head", new MeshStandardMaterial({ color: 5583667, roughness: 0.4 }));
  lips.morphTargetInfluences[0] = Number(params2.get("grin") || 0);
  lips.visible = Number(params2.get("grin") || 0) > 0.01;
  for (const e of asset.json.head.eyes) {
    const eye = new Mesh(new SphereGeometry(asset.json.head.eyeRadius, 32, 16), new MeshStandardMaterial({ color: 13148208, roughness: 0.1 }));
    attach(eye.geometry, "head", eye.material).position.add(new Vector3(...e.center));
  }
  scene.add(new HemisphereLight(14674175, 4208688, 1.2));
  const key = new DirectionalLight(16777215, 2.2);
  key.position.set(0.6, 1, 0.9);
  scene.add(key);
  const rim = new DirectionalLight(16777215, 1);
  rim.position.set(-0.8, 0.5, -0.8);
  scene.add(rim);
  const rig = new Rig(asset, group);
  const pose = params2.get("pose") || "bind";
  if (pose === "test") {
    rig.setEuler("spine1", [8, 0, 0]);
    rig.setEuler("chest", [-6, 10, 0]);
    rig.setEuler("head", [-12, 15, 8]);
    rig.setEuler("jaw", [10, 0, 0]);
    rig.setEuler("earL", [0, 0, -20]);
    rig.setEuler("tail1", [0, 30, 0]);
    rig.setEuler("tail3", [0, 30, 0]);
    rig.setEuler("tail5", [0, 35, 0]);
    group.updateMatrixWorld(true);
    const tL = new Vector3(8e-3, 0.25, 0.13), tR = new Vector3(-8e-3, 0.25, 0.13);
    rig.twoBoneIK("upperArmL", "foreArmL", "handL", tL, new Vector3(0.2, 0.1, -0.1));
    rig.twoBoneIK("upperArmR", "foreArmR", "handR", tR, new Vector3(-0.2, 0.1, -0.1));
    rig.setWorldQuat("handL", rig.handQuat("L", new Vector3(0, 1, 0.8), new Vector3(-1, 0, 0)));
    rig.setWorldQuat("handR", rig.handQuat("R", new Vector3(0, 1, 0.8), new Vector3(1, 0, 0)));
    rig.shareTwist("foreArmL", "handL", 0.5);
    rig.shareTwist("foreArmR", "handR", 0.5);
    for (const f of ["index", "middle", "ring", "pinky"]) {
      rig.curlFinger("L", f, [10, 15, 8]);
      rig.curlFinger("R", f, [60, 80, 40]);
    }
    rig.curlFinger("R", "thumb", [20, 30, 20]);
    rig.b.pelvis.position.y -= 0.03;
    group.updateMatrixWorld(true);
    for (const s of ["L", "R"]) {
      const foot = rig.restWorld["foot" + s].clone();
      const knee = rig.restWorld["shin" + s].clone().add(new Vector3(0, 0.05, 0.3));
      rig.twoBoneIK("thigh" + s, "shin" + s, "foot" + s, foot, knee);
    }
  }
  group.updateMatrixWorld(true);
  const views = {
    front: { pos: [0, 0.26, 1], target: [0, 0.24, 0], fov: 32 },
    q34: { pos: [0.6, 0.38, 0.75], target: [0, 0.22, -0.02], fov: 34 },
    side: { pos: [1, 0.26, 0], target: [0, 0.24, -0.05], fov: 34 },
    face: { pos: [0, 0.39, 0.3], target: [0, 0.375, 0.03], fov: 26 },
    face34: { pos: [0.16, 0.4, 0.26], target: [0, 0.375, 0.03], fov: 26 },
    faceside: { pos: [0.3, 0.385, 0.06], target: [0, 0.375, 0.03], fov: 28 },
    hands: { pos: [0.15, 0.32, 0.45], target: [0, 0.24, 0.12], fov: 28 }
  };
  const v = views[params2.get("view") || "q34"];
  const camera = new PerspectiveCamera(v.fov, innerWidth / innerHeight, 0.01, 10);
  camera.position.set(...v.pos);
  camera.lookAt(...v.target);
  return {
    render() {
      renderer2.render(scene, camera);
    },
    resize(w, h) {
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    }
  };
}

