// src/app/sequence.js
var Sequence = class _Sequence {
  static async create(renderer2, opts = {}) {
    const s = new _Sequence();
    await s.init(renderer2, opts);
    return s;
  }
  async init(renderer2, opts) {
    this.opts = opts;
    this.world = await World.create(renderer2, opts);
    this.choreo = createMemeChoreo();
    this.duration = this.choreo.duration;
    this.ctrl = new CatController(this.world.cat, this.choreo);
    this.camera = this.world.camera;
    this.treat = new Mesh(new CapsuleGeometry(4e-3, 0.03, 6, 12), new MeshStandardMaterial({ color: 9080729, metalness: 0.5, roughness: 0.4 }));
    this.treat.rotation.z = Math.PI / 2;
    this.world.scene.add(this.treat);
    this.camMode = opts.cam || "pov";
  }
  setTime(t) {
    const cam = this.camera;
    const c = this.choreo.sample(t);
    if (this.camMode === "pov") {
      const s = c.shake;
      const n = (k2, f) => fbm1(t * f, k2);
      cam.position.set(c.camPos[0] + n(1, 0.35) * 6e-3 * s, c.camPos[1] + n(2, 0.3) * 5e-3 * s, c.camPos[2] + n(3, 0.33) * 6e-3 * s);
      const tgt = new Vector3(...c.camTarget);
      cam.lookAt(tgt);
      cam.rotateZ(n(4, 0.25) * 0.012 * s);
      cam.rotateX(n(5, 0.9) * 35e-4 * s);
      cam.rotateY(n(6, 0.8) * 35e-4 * s);
      cam.fov = c.camFov;
      cam.updateProjectionMatrix();
      cam.updateMatrixWorld();
      if (this.world.post?.bokeh) this.world.post.bokeh.uniforms.focus.value = cam.position.distanceTo(tgt) * 1;
    }
    const cc = this.ctrl.update(t, cam);
    const mouth = this.world.cat.rig.b.head.localToWorld(new Vector3(0, 0, 0).add(new Vector3(0, -0.019, 0.075)));
    const handPos = new Vector3(0, 0.3, 0.16);
    const k = Math.min(1, cc.human);
    this.treat.visible = cc.treatVis > 0.5 && k > 0.02;
    this.treat.position.lerpVectors(new Vector3(0.25, 0.55, 0.7), t > 1.9 ? mouth : handPos, t > 1.9 ? 1 : k);
  }
  render(t) {
    this.setTime(t);
    this.world.render(t);
  }
  debug(t) {
    this.setTime(t);
    const r = this.world.cat.rig;
    const p = (n) => r.worldPos(n).toArray().map((v) => +v.toFixed(4));
    const c = this.choreo.sample(t);
    return { handL: c.handL, handLSpace: c.handLSpace, wL: p("handL"), eL: p("foreArmL"), sL: p("upperArmL"), chest: p("chest"), pelvis: p("pelvis") };
  }
  resize(w, h) {
    this.world.resize(w, h);
  }
};

// src/main.js
var params = new URLSearchParams(location.search);
var renderer = new WebGLRenderer({ antialias: true, powerPreference: "high-performance", preserveDrawingBuffer: params.has("offline") });
renderer.setPixelRatio(params.has("offline") ? 1 : Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);
var app = { ready: false };
window.__app = app;
async function main() {
  let view;
  if (params.get("mode") === "preview") view = await startPreview(renderer, params);
  else if (params.get("mode") === "rig") view = await startRigTest(renderer, params);
  else if (params.get("mode") === "lookdev") view = await startLookdev(renderer, params);
  else if (params.get("mode") === "scene") view = await startSceneTest(renderer, params);
  else {
    const seq = await Sequence.create(renderer, {
      shells: Number(params.get("shells") || 40),
      post: params.get("post") !== "0",
      exposure: Number(params.get("exp") || 0.85),
      ao: params.get("ao") !== "0",
      dof: params.get("dof") !== "0",
      cam: params.get("cam") || "pov"
    });
    app.seq = seq;
    view = {
      render: (t) => seq.render(t ?? performance.now() / 1e3 % seq.duration),
      resize: (w, h) => seq.resize(w, h)
    };
  }
  app.renderAt = async (t) => {
    view.render(t);
  };
  addEventListener("resize", () => {
    renderer.setSize(innerWidth, innerHeight);
    view.resize(innerWidth, innerHeight);
  });
  app.ready = true;
  if (!params.has("offline")) renderer.setAnimationLoop(() => view.render());
}
main();
